### Instruction:
Implement a version of your own version of quicksort in Python

### Response:
def quicksort(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[0]
    left = []
    right = []

    for num in arr[1:]:
        if num < pivot:
            left.append(num)
        else:
            right.append(num)

    return quicksort(left) + [pivot] + quicksort(right)

if __name__ == '__main__':
    arr = [7, 3, 1, 9, 0]
    print(quicksort(arr))

### Instruction:
Create a code to save the first ten prime numbers in an array.

### Response:
# prime number sieve
def prime_numbers(n): 

    prime = [True for i in range(n+1)] 
    p = 2
    while (p * p <= n): 
        if (prime[p] == True): 
            for i in range(p * p, n+1, p): 
                prime[i] = False
        p += 1

    prime_numbers = []
    for p in range(2, n): 
        if prime[p]: 
            prime_numbers.append(p)
    return prime_numbers[:10]

if __name__ == "__main__":
    n = 100
    print(prime_numbers(n))

