### Input:
word = "abbac"

### Response:
def anagrams(word):
    if len(word) == 1:
        return [word]
    else:
        anagrams_list = []
        for i, letter in enumerate(word):
            for j in anagrams(word[:i]+word[i+1:]):
                anagrams_list.append(letter+j)
        return anagrams_list

