void deleteNode(struct node *node) 
{ 
    struct node *temp = node->next; 
    node->data = temp->data; 

    // Store pointer to the next of node 
    struct node *next_next = temp->next; 

    // Unlink node from linked list 
    free(temp); 

    node->next = next_next; 
}

