    stack = [] 

    for char in exp: 
        if char in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" or char in "0123456789": 
            stack.append(char)

        else: 
            val1 = stack.pop() 
            val2 = stack.pop() 
