public int FindCommonElement(int[] arr1, int[] arr2)
{
    HashSet<int> set = new HashSet<int>();
    foreach (int item in arr1)
    {
        set.Add(item);
    }

    List<int> commons = new List<int>();
    foreach (int item in arr2)
    {
