    Given a maximum value, this function finds the common factors among all pairs of positive integers less than or equal
    to the maximum value using nested for loops.

    :param max_value: The maximum value for the positive integers
    :return: A list of all the common factors
    """

### Solution:

    common_factors = []
    for i in range(1, max_value + 1):
        for j in range(1, max_value + 1):
            factors_i = []
            factors_j = []

            # Finding factors of i
            for k in range(1, i + 1):
                if i % k == 0:
                    factors_i.append(k)

            # Finding factors of j
            for k in range(1, j + 1):
                if j % k == 0:
                    factors_j.append(k)

            # Finding common factors
            for k in factors_i:
                if k in factors_j and k not in common_factors:
                    common_factors.append(k)

    return common_factors


